import local.castle.tv.*;
public class GrandRegressionTest {
 static void c(boolean v,String s){if(!v)throw new AssertionError(s);}
 public static void main(String[] a){c(RealmAmbience.sceneHour(12,2,10f)==10&&RealmAmbience.sceneHour(12,1,23f)==23,"scene preview overrides forced lighting");c(RealmAmbience.sceneHour(12,2,null)==23&&RealmAmbience.sceneHour(12,1,null)==10&&RealmAmbience.sceneHour(12,0,null)==12,"normal lighting preferences retained");for(int h=6;h<17;h++)c(RealmAmbience.lamps(h)==0,"morning/day lamps completely off");c(RealmAmbience.lamps(5.99f)==1&&RealmAmbience.lamps(20)==1,"night lamps lit");c(RealmAmbience.lamps(18)>.25f&&RealmAmbience.lamps(18)<.3f,"gentle dusk ignition");for(int h=0;h<24;h++)c(RealmAmbience.butterflies(h)!=RealmAmbience.fireflies(h),"day insects and night fireflies exclusive");c(RealmAmbience.glass(0)==0xff26343d&&RealmAmbience.glass(1)==0xffffdb8c,"glass itself changes from dark to warm");String video="https://youtube.com/watch?v=abcdefghijk";c(!TvCardPolicy.rowKey("app",video,true).equals(TvCardPolicy.rowKey("app",video,false)),"history is not dropped by recommendation duplicate");c(TvCardPolicy.rowKey("app",video,true).equals(TvCardPolicy.rowKey("app",video,true)),"duplicates in same list still match");SourceRefresh r=new SourceRefresh();r.begin(0,"old");r.pause(2000);c(!r.done(100000),"paused refresh never expires in background");r.resume(102000);c(!r.done(144999)&&r.done(145000),"45 second deadline excludes time away");r.finish();r.begin(0,"old");r.observe(10000,"new");r.pause(11000);r.resume(21000);c(!r.done(22499)&&r.done(22500),"quiet period excludes paused time");System.out.println("PASS: clock lamps, dark glass, exclusive insects, separate history keys and background refresh pause");}
}
